using System.Security.Cryptography;
using System.Text;
using AgentEval.Memory.External.Models;

namespace AgentEval.Memory.External.LongMemEval;

/// <summary>
/// A small AgentEval-authored corpus of questions whose answers depend on the clock, shipped inside
/// the assembly so the probe runs with no download.
/// </summary>
/// <remarks>
/// <para>
/// <b>This is not LongMemEval and its scores are not comparable with LongMemEval's.</b> It is
/// twelve authored questions in the LongMemEval file format, and it exists because the original
/// corpus cannot express what it measures: every temporal question there is answerable from dates
/// printed in the prompt, so a system that stores no time at all still scores well, and prospective
/// memory — something stated as not yet true — has no questions at all.
/// </para>
/// <para>
/// The corpus rule that gives it teeth: <b>no message content contains an absolute date or a
/// four-digit year</b>. Every temporal expression a speaker uses is relative — "eight weeks from
/// today", "the first Monday of next month", "a fortnight from tomorrow" — so resolving it requires
/// the session's own timestamp, and answering the question requires comparing that against the
/// instant the question is asked. Run it under
/// <see cref="TemporalGroundingMode.TimestampsOnly"/> and a system that stamps messages with
/// ingestion time has nothing to read.
/// </para>
/// <para>
/// Three question types, four questions each. <c>temporal-as-of</c> asks what was true at a past
/// moment; <c>temporal-current</c> asks what is true now; <c>prospective-memory</c> asks about
/// something stated as not yet true, where the honest answer depends on whether the moment has
/// since arrived. Twelve questions is a probe, not a benchmark: it is large enough to show that a
/// system ignores timestamps and far too small to rank two systems that do not.
/// </para>
/// <para>
/// The corpus is generated by <c>tools/gen_timegrounded_corpus.py</c>, which derives every absolute
/// date in every gold answer from the session timestamps rather than accepting a typed one, so the
/// arithmetic in the answers cannot drift from the arithmetic in the conversations.
/// </para>
/// </remarks>
public static class LongMemEvalTimeGroundedCorpus
{
    /// <summary>Identifier for this corpus and version, for recording which probe a run used.</summary>
    public const string CorpusId = "agenteval-timegrounded-v1";

    /// <summary>Questions the corpus contains.</summary>
    public const int QuestionCount = 12;

    /// <summary>Question type for "what was true at a past moment".</summary>
    public const string AsOfQuestionType = "temporal-as-of";

    /// <summary>Question type for "what is true now".</summary>
    public const string CurrentQuestionType = "temporal-current";

    /// <summary>Question type for "something stated as not yet true".</summary>
    public const string ProspectiveQuestionType = "prospective-memory";

    private static readonly string ResourceSuffix = $"{CorpusId}.json";

    /// <summary>
    /// Reads the corpus JSON exactly as shipped — for writing to disk, hashing, or loading through
    /// the ordinary <see cref="ExternalBenchmarkOptions.DatasetPath"/> route.
    /// </summary>
    public static string ReadJson()
    {
        var assembly = typeof(LongMemEvalTimeGroundedCorpus).Assembly;
        var resourceName = assembly.GetManifestResourceNames()
            .FirstOrDefault(name => name.EndsWith(ResourceSuffix, StringComparison.Ordinal))
            ?? throw new FileNotFoundException(
                $"Embedded time-grounded corpus '{ResourceSuffix}' was not found in " +
                $"{assembly.GetName().Name}.");

        using var stream = assembly.GetManifestResourceStream(resourceName)!;
        using var reader = new StreamReader(stream);
        return reader.ReadToEnd();
    }

    /// <summary>
    /// SHA-256 over the corpus text, so a run can record which probe produced its numbers.
    /// </summary>
    /// <remarks>
    /// Newline-normalized before hashing, for the same reason the judge-prompt fingerprint is: the
    /// file is embedded from a git checkout, and a value that changed when a run moved from a
    /// Windows machine to a Linux runner would report "different corpus" for a run that used the
    /// same one. It identifies the corpus <i>text</i>, not the bytes of one checkout.
    /// </remarks>
    public static string Sha256()
    {
        var normalized = ReadJson().Replace("\r\n", "\n", StringComparison.Ordinal);
        return Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(normalized))).ToLowerInvariant();
    }

    /// <summary>
    /// Loads the corpus, applying the same selection rules any dataset gets — budget, stratification,
    /// question-type filter, abstention policy, seed.
    /// </summary>
    /// <param name="options">Selection options. Null loads every question.</param>
    public static IReadOnlyList<LongMemEvalEntry> Load(ExternalBenchmarkOptions? options = null)
        => LongMemEvalDataLoader.LoadFromJson(ReadJson(), options ?? new ExternalBenchmarkOptions());

    /// <summary>
    /// Options that run the corpus the way it is meant to be run: timestamps delivered through the
    /// typed channel, and the harness's in-text dates removed.
    /// </summary>
    /// <remarks>
    /// Pair it with <see cref="ControlOptions"/>. The difference between the two scores is the
    /// measurement — a system that honours timestamps scores the same in both, and one that reads
    /// dates out of the text drops.
    /// </remarks>
    public static ExternalBenchmarkOptions ProbeOptions => new()
    {
        DatasetMode = CorpusId,
        TemporalGrounding = TemporalGroundingMode.TimestampsOnly,
        HistoryInjectionMode = HistoryInjectionMode.StructuredChatHistory,
        StratifiedSampling = true,
        PreserveSessionBoundaries = true,
        IncludeTimestamps = true
    };

    /// <summary>
    /// The control arm for <see cref="ProbeOptions"/>: the same corpus with the in-text date
    /// scaffolding left in place, so the timestamps are not the only channel.
    /// </summary>
    public static ExternalBenchmarkOptions ControlOptions => new()
    {
        DatasetMode = $"{CorpusId}-control",
        TemporalGrounding = TemporalGroundingMode.TimestampsAndText,
        HistoryInjectionMode = HistoryInjectionMode.StructuredChatHistory,
        StratifiedSampling = true,
        PreserveSessionBoundaries = true,
        IncludeTimestamps = true
    };
}
